from typing import Dict

def euler(space: Dict[int, int]) -> int:
    return sum((1 if d % 2 == 0 else -1) * c for d, c in space.items())

def reflect(space: Dict[int, int]) -> Dict[int, int]:
    return {-d: c for d, c in space.items() if c}

if __name__ == "__main__":
    x = {-2: 3, -1: 5, 0: 7, 3: 11}
    rx = reflect(x)
    print(x, euler(x))
    print(rx, euler(rx))
    assert euler(rx) == euler(x)

from typing import Dict

def convolve(x: Dict[int, int], y: Dict[int, int]) -> Dict[int, int]:
    z: Dict[int, int] = {}
    for a, ca in x.items():
        for b, cb in y.items():
            z[a + b] = z.get(a + b, 0) + ca * cb
    return {d: c for d, c in z.items() if c}

def coordinates(x: Dict[int, int]) -> tuple[int, int]:
    return sum(x.values()), sum((1 if d % 2 == 0 else -1) * c for d, c in x.items())

if __name__ == "__main__":
    x, y = {0: 2, 1: 3}, {0: 5, 1: -1}
    z = convolve(x, y)
    print(z, coordinates(z))
    assert coordinates(z) == tuple(a*b for a,b in zip(coordinates(x), coordinates(y)))

